import { type ReactNode } from "react";
import { Badge, Button, Group, Stack, Text, Title } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { MediaFrame } from "../components/media-frame";
import { tpl, urlOf } from "../utils";
import type { Post, PostLabels } from "../blocks/post-card.types";

export type PostFeatureProps = {
  p: Post;
  labels: PostLabels;
};

export function PostFeature({ p, labels }: PostFeatureProps) {
  return (
    <Stack gap="4" align="stretch" className="border-t border-border pt-6" data-testid="post-feature">
